Now I understand the structure. Let me implement the `file_metadata` tool.

Requirements:
1. `file_metadata` for files under the workspace `data` directory.
2. Requires `path` parameter.
3. Must reject traversal (e.g., `../`).
4. Must reject missing files.
5. Returns relative path, byte size, and lowercase extension as text content.
6. The tool schema must be strict.
7. Unknown tools must reject.
8. Do not expose file contents.

Let me look at the test: `const r=await callTool('file_metadata',{path:'readme.txt'});assert.match(r.content[0].text,/\.txt/);assert.match(r.content[0].text,/6/)`.

So for `readme.txt` (content "hello\n" = 6 bytes), the result text must contain `.txt` and `6`.

Let me design the server:

```js
import path from 'node:path';
import fs from 'node:fs';

const DATA_DIR = path.resolve('data');

function isPathSafe(relPath) {
  // Normalize and reject traversal
  // Resolve relative to DATA_DIR and ensure it's within
  const resolved = path.resolve(DATA_DIR, relPath);
  if (resolved !== DATA_DIR && !resolved.startsWith(DATA_DIR + path.sep)) {
    return null;
  }
  return resolved;
}

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata for a file under the workspace data directory.',
      inputSchema: {
        type: 'object',
        properties: {
          path: { type: 'string', description: 'Path relative to the data directory.' }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { path: relPath } = args;
  if (typeof relPath !== 'string' || relPath.length === 0) {
    throw new Error('path is required');
  }
  // Reject traversal
  const resolved = isPathSafe(relPath);
  if (resolved === null) {
    throw new Error('path traversal is not allowed');
  }
  // Must exist and be a file
  let stat;
  try {
    stat = await fs.promises.stat(resolved);
  } catch (e) {
    throw new Error('file not found');
  }
  if (!stat.isFile()) {
    throw new Error('path is not a file');
  }
  const ext = path.extname(resolved).toLowerCase();
  const text = `path: ${relPath}\nsize: ${stat.size}\nextension: ${ext}`;
  return {
    content: [{ type: 'text', text }]
  };
}
```

